prompt --application/shared_components/logic/application_processes/app_user_cargo
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(20014317405414700)
,p_process_sequence=>1
,p_process_point=>'BEFORE_HEADER'
,p_process_name=>'APP_USER_CARGO'
,p_static_id=>'app-user-cargo'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'  SELECT G.nome',
'    INTO :APP_USER_CARGO',
'    FROM COLABORADOR C',
'    JOIN CARGO G ON G.id_cargo = C.id_cargo',
'   WHERE UPPER(TRIM(C.login_apex)) = UPPER(TRIM(:APP_USER));',
'EXCEPTION',
'  WHEN NO_DATA_FOUND THEN',
unistr('    :APP_USER_CARGO := ''SEM V\00CDNCULO'';'),
'  WHEN TOO_MANY_ROWS THEN',
unistr('    :APP_USER_CARGO := ''M\00DALTIPLOS V\00CDNCULOS'';'),
'  WHEN OTHERS THEN',
'    :APP_USER_CARGO := ''ERRO AO CARREGAR CARGO'';',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_version_scn=>'SH256:LBjKa0gXDkthWs89Yy-aK6jwgL0ELxpI9j2EEPe6M-o'
);
end;
/
prompt --application/shared_components/logic/application_processes/app_user_foto
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(20812895050971593)
,p_process_sequence=>1
,p_process_point=>'BEFORE_HEADER'
,p_process_name=>'APP_USER_FOTO'
,p_static_id=>'app-user-foto'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- APP_USER_FOTO = caminho relativo a #APP_FILES# (o prefixo fica no HTML da Global Page).',
'-- Sem foto, fica nulo: a <img> falha e o header mostra APP_USER_INICIAIS.',
'BEGIN',
'  SELECT',
'    CASE',
'      WHEN TRIM(C.foto_url) IS NULL',
'           OR C.foto_url = ''#APP_FILES#Fotos Colaboradores/'' THEN',
'        NULL',
'      ELSE',
'        apex_page.get_url(p_page => 44, p_x01 => regexp_substr(trim(C.foto_url), ''[^/]+$''))',
'    END,',
'    UPPER(',
'      SUBSTR(TRIM(NVL(C.primeiro_nome, C.nome_completo)), 1, 1) ||',
'      SUBSTR(TRIM(NVL(C.ultimo_nome,',
'        SUBSTR(TRIM(C.nome_completo), NULLIF(INSTR(TRIM(C.nome_completo), '' '', -1), 0) + 1))), 1, 1)',
'    )',
'    INTO :APP_USER_FOTO, :APP_USER_INICIAIS',
'    FROM COLABORADOR C',
'   WHERE UPPER(TRIM(C.login_apex)) = UPPER(TRIM(:APP_USER));',
'EXCEPTION',
'  WHEN OTHERS THEN',
'    :APP_USER_FOTO := NULL;',
'    :APP_USER_INICIAIS := UPPER(SUBSTR(:APP_USER, 1, 1));',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_version_scn=>'SH256:I9_S51FPIJCkrZ3wTEmq8Lj01jmfY3AW6xZf7tZ0Gqs'
);
end;
/
prompt --application/shared_components/logic/application_processes/g_nome_empresa
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(14810551092227182)
,p_process_sequence=>1
,p_process_point=>'BEFORE_HEADER'
,p_process_name=>'G_NOME_EMPRESA'
,p_static_id=>'g-nome-empresa'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'  SELECT E.nome',
'    INTO :G_NOME_EMPRESA',
'    FROM COLABORADOR C',
'    JOIN EMPRESA E ON E.id_empresa = C.id_empresa',
'   WHERE UPPER(TRIM(C.login_apex)) = UPPER(TRIM(:APP_USER));',
'EXCEPTION',
'  WHEN NO_DATA_FOUND THEN',
'    :G_NOME_EMPRESA := ''sem empresa vinculada'';',
'  WHEN TOO_MANY_ROWS THEN',
'    :G_NOME_EMPRESA := ''mais de uma empresa vinculada'';',
'  WHEN OTHERS THEN',
unistr('    :G_NOME_EMPRESA := ''empresa indispon\00EDvel'';'),
'    log_pkg.erro(SQLERRM, ''G_NOME_EMPRESA'');',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_version_scn=>'SH256:VqQMcS72c7_oiWshCPDzp03DSTwOz9NfAk2_LFMCxys'
);
end;
