prompt --application/pages/page_00003
begin
wwv_flow_imp_page.create_page(
 p_id=>3
,p_name=>'Organograma'
,p_alias=>'ORGANOGRAMA'
,p_step_title=>'Organograma'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'const ORG_ITEM_FOCO         = "P3_ID_FOCO";',
'const ORG_REGIAO            = "organograma";',
'const ORG_PROCESSO_DETALHES = "ORG_DETALHES";',
'',
'let orgDrawer = null;',
'let orgPedido = 0;',
'',
'function orgId(valor) {',
'  const id = Number(valor);',
'  return Number.isFinite(id) && id > 0 ? id : null;',
'}',
'',
unistr('/* Fun\00E7\00E3o atualizada com tratamento seguro para a regi\00E3o */'),
'function orgIrPara(valor) {',
'  const id = orgId(valor);',
'  if (!id) return;',
'',
'  // 1. Atualiza o valor do item no APEX',
'  apex.item(ORG_ITEM_FOCO).setValue(String(id));',
'',
unistr('  // 2. Tenta atualizar pela API nativa de regi\00E3o ou aplica o refresh no container HTML'),
'  const reg = apex.region(ORG_REGIAO);',
'  if (reg) {',
'    reg.refresh();',
'  } else {',
unistr('    // Fallback para regi\00F5es Dynamic Content sem chave registrada'),
'    $("#" + ORG_REGIAO).trigger("apexrefresh");',
'    $(".org").trigger("apexrefresh");',
'  }',
'}',
'',
'function orgObterDrawer() {',
'  if (orgDrawer) return orgDrawer;',
'',
'  orgDrawer = document.createElement("dialog");',
'  orgDrawer.className = "org-drawer";',
'  orgDrawer.setAttribute("aria-labelledby", "org-drawer-nome");',
'  orgDrawer.innerHTML = ''<div class="org-drawer__painel"></div>'';',
'  orgDrawer.addEventListener("click", orgCliqueNoDrawer);',
'  document.body.appendChild(orgDrawer);',
'',
'  return orgDrawer;',
'}',
'',
'/* Fotos: o PL/SQL manda o caminho em data-org-foto ("Fotos Colaboradores/x.jpg");',
'   aqui vira URL dos Static Application Files. Sem foto, ficam as iniciais. */',
'function orgCarregarFotos(raiz) {',
'  if (!raiz) return;',
'  raiz.querySelectorAll("img[data-org-foto]").forEach(function (img) {',
'    const nome = img.dataset.orgFoto.split("/").pop();',
'    img.removeAttribute("data-org-foto");',
'    img.src = location.pathname.replace(/[^/]*$/, "") + "foto?session=" + apex.env.APP_SESSION + "&x01=" + encodeURIComponent(nome);',
'  });',
'}',
'',
'function orgEstado(html) {',
'  return ''<div class="org-drawer__estado">'' + html + "</div>";',
'}',
'',
'function orgAbrirDetalhes(valor) {',
'  const id = orgId(valor);',
'  if (!id) return;',
'',
'  const drawer = orgObterDrawer();',
'  const painel = drawer.firstElementChild;',
'  const pedido = ++orgPedido;',
'',
'  painel.setAttribute("aria-busy", "true");',
'',
'  painel.innerHTML = orgEstado(',
'    ''<span class="org-spinner" aria-hidden="true"></span><p>Carregando detalhes...</p>''',
'  );',
'',
'  if (!drawer.open) drawer.showModal();',
'',
'  apex.server.process(',
'    ORG_PROCESSO_DETALHES,',
'    { x01: id },',
'    { dataType: "text" }',
'  )',
'  .done(function (html) {',
'    if (pedido !== orgPedido) return;',
'',
'    painel.innerHTML = html;',
'    orgCarregarFotos(painel);',
'',
'    const titulo = painel.querySelector("#org-drawer-nome");',
'    if (titulo) titulo.focus();',
'  })',
'  .fail(function () {',
'    if (pedido !== orgPedido) return;',
'',
'    painel.innerHTML = orgEstado(',
unistr('      "<p>N\00E3o foi poss\00EDvel carregar os detalhes.</p>" +'),
'      ''<button type="button" class="org-btn org-btn--auto" data-acao="detalhe" data-id="'' + id + ''">'' +',
'      "Tentar novamente</button>" +',
'      ''<button type="button" class="org-link" data-acao="fechar">Fechar</button>''',
'    );',
'  })',
'  .always(function () {',
'    if (pedido === orgPedido) {',
'      painel.removeAttribute("aria-busy");',
'    }',
'  });',
'}',
'',
'function orgCopiar(botao) {',
'  if (!navigator.clipboard) return;',
'',
'  const aviso = botao.parentElement.querySelector(".org-sr");',
'',
'  navigator.clipboard.writeText(botao.dataset.valor).then(function () {',
'    botao.classList.add("is-copiado");',
'    botao.setAttribute("aria-label", "E-mail copiado");',
'',
'    if (aviso) {',
'      aviso.textContent = "E-mail copiado.";',
'    }',
'',
'    setTimeout(function () {',
'      botao.classList.remove("is-copiado");',
'      botao.setAttribute("aria-label", "Copiar e-mail");',
'',
'      if (aviso) {',
'        aviso.textContent = "";',
'      }',
'    }, 2000);',
'  });',
'}',
'',
'function orgCliqueNoDrawer(ev) {',
'  const drawer = ev.currentTarget;',
'',
'  if (ev.target === drawer) {',
'    drawer.close();',
'    return;',
'  }',
'',
'  const alvo = ev.target.closest("[data-acao]");',
'  if (!alvo) return;',
'',
'  switch (alvo.dataset.acao) {',
'    case "fechar":',
'      drawer.close();',
'      break;',
'',
'    case "detalhe":',
'      orgAbrirDetalhes(alvo.dataset.id);',
'      break;',
'',
'    case "equipe":',
'      drawer.close();',
'      orgIrPara(alvo.dataset.id);',
'      break;',
'',
'    case "copiar":',
'      orgCopiar(alvo);',
'      break;',
'  }',
'}'))
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'orgCarregarFotos(document);',
'',
'// Delegado no document para garantir a captura dos cliques dentro do container .org',
'$(document).on("click", ".org [data-acao]", function () {',
'    if (this.dataset.acao === "foco") {',
'        orgIrPara(this.dataset.id);',
'    } else if (this.dataset.acao === "detalhe") {',
'        orgAbrirDetalhes(this.dataset.id);',
'    }',
'});',
'',
unistr('// Captura a atualiza\00E7\00E3o da regi\00E3o para recarregar fotos e ajustar o foco de acessibilidade'),
'$("#organograma").on("apexafterrefresh", function () {',
'    orgCarregarFotos(this);',
'',
'    const titulo = document.getElementById("org-foco-nome");',
'    if (titulo) {',
'        titulo.focus({',
'            preventScroll: true',
'        });',
'    }',
'});'))
,p_css_file_urls=>'#APP_FILES#organograma#MIN#.css'
,p_step_template=>4073832297226169690
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'25'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(10219169110387935)
,p_plug_name=>'Breadcrumb'
,p_static_id=>'breadcrumb'
,p_region_template_options=>'#DEFAULT#:t-BreadcrumbRegion--useBreadcrumbTitle'
,p_component_template_options=>'#DEFAULT#'
,p_escape_on_http_output=>'N'
,p_plug_template=>2532939663579242476
,p_plug_display_sequence=>10
,p_plug_display_point=>'REGION_POSITION_01'
,p_plug_item_display_point=>'ABOVE'
,p_menu_id=>wwv_flow_imp.id(10015682119229680)
,p_plug_source_type=>'NATIVE_BREADCRUMB'
,p_menu_template_id=>4073839682315169711
,p_plug_query_headings_type=>'COLON_DELMITED_LIST'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(31837999345958904)
,p_plug_name=>'Organograma Principal'
,p_static_id=>'organograma'
,p_region_name=>'organograma'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>4502917002193490937
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  v_id_foco number;',
'begin',
'  v_id_foco := to_number(:P3_ID_FOCO default null on conversion error);',
'',
unistr('  -- Se n\00E3o foi informado nenhum ID na URL/Sess\00E3o, assume o ID do usu\00E1rio logado'),
