prompt --application/pages/page_00004
begin
wwv_flow_imp_page.create_page(
 p_id=>4
,p_name=>'Chat'
,p_alias=>'CHAT'
,p_step_title=>'Chat'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('// Polling do chat: a cada 1 s pergunta ao servidor (CH_VERIFICAR_MSGS) qual \00E9 a'),
unistr('// assinatura da conversa aberta e s\00F3 recarrega a regi\00E3o Mensagens quando ela \00E9'),
unistr('// diferente da que est\00E1 na tela. Ver modulos/chat/Etapas-chat.md \00A71.'),
'const chChat = (function () {',
unistr('    const REGIAO_ID         = "msgs"; // Static ID da regi\00E3o Mensagens (passo 1.1, item 4)'),
'    const INTERVALO_MS      = 1000;  // 1 s',
'    const INTERVALO_ERRO_MS = 5000;  // depois de um erro de rede, espera mais',
unistr('    const FOLGA_FIM_PX      = 40;    // "est\00E1 no fim" = a menos de 40 px do fim'),
'    const LIMITE_REFRESH_MS = 10000; // destrava se um refresh nunca terminar',
'',
'    let timer          = null;',
unistr('    let consultando    = false; // h\00E1 uma chamada ao CH_VERIFICAR_MSGS em andamento'),
unistr('    let atualizandoDes = 0;     // quando come\00E7ou o refresh da regi\00E3o (0 = nenhum)'),
unistr('    let forcarFim      = false; // pr\00F3ximo refresh rola at\00E9 o fim (envio de mensagem)'),
'    let irAoFim        = true;',
'    let topoSalvo      = 0;',
unistr('    let canalNaTela    = null;  // canal cujas mensagens est\00E3o renderizadas'),
'',
'    function canalAtual() {',
'        return apex.item("P4_CANAL_ID").getValue();',
'    }',
'',
unistr('    // Elemento da regi\00E3o Mensagens. Usa o Static ID "msgs" se ele vier no HTML;'),
unistr('    // sen\00E3o, sobe a partir do relat\00F3rio (report_<id>_catch) at\00E9 o id interno R<id>.'),
unistr('    // Assim o polling funciona mesmo que o Static ID n\00E3o chegue \00E0 p\00E1gina.'),
'    function regiaoEl() {',
'        const porId = document.getElementById(REGIAO_ID);',
'        if (porId) {',
'            return porId;',
'        }',
'        const relatorio = document.querySelector(".ch-chat [id^=''report_''][id$=''_catch'']");',
'        return relatorio ? relatorio.closest("[id^=''R'']") : null;',
'    }',
'',
'    function lista() {',
'        const el = regiaoEl();',
'        return el ? el.querySelector(".ch-msgs") : null;',
'    }',
'',
'    function atualizando() {',
'        return atualizandoDes > 0 && Date.now() - atualizandoDes < LIMITE_REFRESH_MS;',
'    }',
'',
unistr('    // mesma regra do CH_VERIFICAR_MSGS: "<id da \00FAltima mensagem>:<quantidade>"'),
'    function assinaturaNaTela() {',
'        const el     = regiaoEl();',
'        const msgs   = el ? el.querySelectorAll(".ch-msg[data-id]") : [];',
'        const ultima = msgs.length ? msgs[msgs.length - 1].dataset.id : "0";',
'        return ultima + ":" + msgs.length;',
'    }',
'',
'    function recarregar() {',
'        const el = regiaoEl();',
'        if (!el) {',
unistr('            console.warn("chChat: regi\00E3o Mensagens n\00E3o encontrada na p\00E1gina");'),
'            return;',
'        }',
'        apex.region(el.id).refresh();',
'    }',
'',
'    function agendar(ms) {',
'        clearTimeout(timer);',
'        timer = setTimeout(verificar, ms === undefined ? INTERVALO_MS : ms);',
'    }',
'',
'    function verificar() {',
'        const canal = canalAtual();',
'',
unistr('        // sem conversa aberta, aba escondida ou algo j\00E1 em andamento: s\00F3 reagenda'),
'        if (!canal || document.hidden || consultando || atualizando()) {',
'            agendar();',
'            return;',
'        }',
'',
'        consultando = true;',
'        let espera = INTERVALO_MS;',
'',
'        apex.server.process("CH_VERIFICAR_MSGS", { x01: canal }, { dataType: "json" })',
'            .done(function (resp) {',
unistr('                // trocou de conversa enquanto a resposta vinha, ou j\00E1 h\00E1 refresh: ignora'),
'                if (canal !== canalAtual() || atualizando()) {',
'                    return;',
'                }',
'                if (resp && resp.assinatura !== assinaturaNaTela()) {',
unistr('                    // try/catch: um erro aqui n\00E3o pode impedir o .always de liberar o ciclo'),
'                    try {',
'                        recarregar();',
'                    } catch (e) {',
'                        console.error("chChat: falha ao atualizar a conversa", e);',
'                    }',
'                }',
'            })',
'            .fail(function () {',
'                espera = INTERVALO_ERRO_MS;',
'            })',
'            .always(function () {',
'                consultando = false;',
'                agendar(espera);',
'            });',
'    }',
'',
unistr('    // vale para qualquer refresh da regi\00E3o: polling, abrir contato e enviar'),
'    function antesDoRefresh() {',
'        atualizandoDes = Date.now();',
'        const l = lista();',
'        const outraConversa = canalNaTela !== canalAtual();',
'        irAoFim = forcarFim || outraConversa || !l ||',
'                  l.scrollHeight - l.scrollTop - l.clientHeight < FOLGA_FIM_PX;',
'        topoSalvo = l ? l.scrollTop : 0;',
'    }',
'',
'    function depoisDoRefresh() {',
'        const l = lista();',
'        if (l) {',
'            l.scrollTop = irAoFim ? l.scrollHeight : topoSalvo;',
'        }',
'        canalNaTela    = canalAtual();',
'        forcarFim      = false;',
'        atualizandoDes = 0;',
unistr('        agendar(); // a pr\00F3xima verifica\00E7\00E3o conta a partir de agora'),
'    }',
'',
unistr('    // s\00F3 reage aos eventos da regi\00E3o Mensagens (a lista de contatos tamb\00E9m \00E9 relat\00F3rio).'),
unistr('    // "contains" e n\00E3o "===": o relat\00F3rio dispara o evento num elemento DENTRO da'),
unistr('    // regi\00E3o (report_<id>_catch), e ele sobe at\00E9 o document.'),
'    function daRegiao(evento) {',
'        const el = regiaoEl();',
'        return !!el && el.contains(evento.target);',
'    }',
'',
'    function iniciar() {',
unistr('        // ligado no document: funciona com qualquer id que a regi\00E3o tenha'),
'        apex.jQuery(document)',
'            .on("apexbeforerefresh", function (e) { if (daRegiao(e)) { antesDoRefresh(); } })',
'            .on("apexafterrefresh",  function (e) { if (daRegiao(e)) { depoisDoRefresh(); } });',
'',
unistr('        // voltou para a aba: verifica na hora em vez de esperar o pr\00F3ximo ciclo'),
'        document.addEventListener("visibilitychange", function () {',
'            if (!document.hidden) {',
'                agendar(0);',
'            }',
'        });',
'',
'        agendar();',
'    }',
'',
'    return {',
'        iniciar: iniciar,',
unistr('        // chamado pela DA "Enviar Mensagem": quem envia quer ver a pr\00F3pria mensagem'),
'        irParaFim: function () { forcarFim = true; }',
'    };',
'})();'))
,p_javascript_code_onload=>'chChat.iniciar();'
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* ============================================',
unistr('   CHAT \2014 P\00E1gina 4'),
'   ============================================ */',
'',
':root {',
'    --ch-topbar-h: 40px;',
'    --ch-list-w: 260px;',
'',
'    --ch-blue: var(--cx-primaria);',
'    --ch-blue-soft: var(--cx-primaria-suave);',
'    --ch-bubble-in: var(--cx-tag);',
'',
'    --ch-border: var(--cx-borda);',
'    --ch-surface: var(--cx-superficie-2);',
'',
'    --ch-text: var(--cx-texto);',
'    --ch-text-dim: var(--cx-texto-2);',
'    --ch-text-faint: var(--cx-texto-3);',
'',
'    --ch-avatar-bg: var(--cx-primaria-suave);',
'    --ch-avatar-fg: var(--cx-primaria);',
'',
'    --ch-online: #22C55E;',
'    --ch-ausente: #F59E0B;',
'    --ch-offline: #D1D5DB;',
'',
'    --ch-radius: var(--cx-raio-card);',
'    --ch-avatar-size: 34px;',
'}',
'',
'/* ---- reset do container do Universal Theme ---- */',
'html,',
'body {',
'    height: 100%;',
'}',
'',
'.ch-page .t-Body-content,',
'.ch-page .t-Body-contentInner,',
'.ch-page .t-Body-main {',
'    padding: 0 !important;',
'    margin: 0 !important;',
'    max-width: none;',
'}',
'',
'.ch-page .t-Body-content {',
'    overflow: hidden;',
'}',
'',
'/* ---- estrutura de duas colunas ---- */',
'.ch-shell {',
'    display: grid;',
'    grid-template-columns: var(--ch-list-w) 1fr;',
'    grid-template-rows: minmax(0, 1fr); /* impede a linha de crescer */',
'    height: calc(100vh - var(--ch-topbar-h));',
'    overflow: hidden;',
'    background: #fff;',
'}',
'',
'/* wrappers do APEX (.container/.row, inclusive os internos) somem do layout:',
'   .ch-list e .ch-chat viram itens do grid, e as colunas internas viram',
unistr('   itens flex direto da regi\00E3o Conversa */'),
'.ch-shell>div,',
'.ch-shell .container,',
'.ch-shell .row {',
'    display: contents;',
'}',
'',
'/* ============================================',
'   Coluna de contatos',
'   ============================================ */',
'',
'.ch-list {',
'    background: #fff;',
'    border-right: 1px solid var(--ch-border);',
'    display: flex;',
'    flex-direction: column;',
'    min-height: 0;',
'    overflow: hidden;',
'}',
'',
unistr('/* repassa a altura: regi\00E3o \2192 #report_catch */'),
'.ch-list>div,',
'.ch-list>div>div {',
'    display: flex;',
'    flex-direction: column;',
'    flex: 1 1 auto;',
'    min-height: 0;',
'}',
'',
'.ch-contacts {',
'    display: flex;',
'    flex-direction: column;',
'    flex: 1 1 auto;',
'    min-height: 0;',
'    overflow-y: auto;',
'}',
'',
unistr('/* cabe\00E7alho do departamento: bot\00E3o que abre/fecha o grupo */'),
'.ch-dept {',
'    position: sticky;',
'    top: 0;',
'    z-index: 1;',
'    flex: 0 0 auto;',
'    display: flex;',
'    align-items: center;',
'    gap: 8px;',
'    width: 100%;',
'    padding: 10px 16px;',
'    border: none;',
'    border-top: 1px solid var(--ch-border);',
'    border-bottom: 1px solid var(--ch-border);',
'    background: var(--ch-surface);',
'    font: inherit;',
'    font-size: 11px;',
'    font-weight: 600;',
'    letter-spacing: .04em;',
'    text-transform: uppercase;',
'    text-align: left;',
'    color: var(--ch-text-dim);',
'    cursor: pointer;',
'}',
'',
'.ch-dept:first-child {',
'    border-top: none;',
'}',
'',
'.ch-dept:hover {',
'    color: var(--ch-text);',
'}',
'',
'.ch-dept:focus-visible {',
'    outline: 2px solid var(--ch-blue);',
'    outline-offset: -2px;',
'}',
'',
'.ch-dept-ico {',
'    font-size: 10px;',
'    transition: transform .15s ease;',
'}',
'',
'.ch-dept[aria-expanded="true"] .ch-dept-ico {',
'    transform: rotate(90deg);',
'}',
'',
'.ch-dept-nome {',
'    flex: 1 1 auto;',
'    min-width: 0;',
'    white-space: nowrap;',
'    overflow: hidden;',
'    text-overflow: ellipsis;',
'}',
'',
'.ch-dept-qtd {',
'    flex: 0 0 auto;',
'    font-weight: 500;',
'    letter-spacing: 0;',
'    color: var(--ch-text-faint);',
'}',
'',
unistr('/* departamentos come\00E7am colapsados; a DA "Abrir/fechar'),
'   marca os contatos do grupo aberto com .is-visivel */',
'.ch-contacts .ch-contact:not(.is-visivel) {',
'    display: none;',
'}',
'',
'.ch-contact {',
'    display: flex;',
'    flex: 0 0 auto;',
'    align-items: center;',
'    gap: 10px;',
'    padding: 10px 16px;',
'    text-decoration: none;',
'    color: inherit;',
'    border-left: 3px solid transparent;',
'    transition: background .12s ease;',
'}',
'',
'.ch-contact:hover {',
'    background: var(--ch-surface);',
'}',
'',
'.ch-contact:focus-visible {',
'    outline: 2px solid var(--ch-blue);',
'    outline-offset: -2px;',
'}',
'',
'.ch-contact.is-active {',
'    background: var(--ch-blue-soft);',
'    border-left-color: var(--ch-blue);',
'}',
'',
unistr('/* ---- avatar + status (lista e cabe\00E7alho da conversa) ---- */'),
'.ch-avatar-wrap {',
'    position: relative;',
'    flex: 0 0 var(--ch-avatar-size);',
'}',
'',
'.ch-avatar {',
'    position: relative;',
'    width: var(--ch-avatar-size);',
'    height: var(--ch-avatar-size);',
'    border-radius: 50%;',
'    overflow: hidden;',
'    display: flex;',
'    align-items: center;',
'    justify-content: center;',
'    font-size: 12px;',
'    font-weight: 600;',
'    background: var(--ch-avatar-bg);',
'    color: var(--ch-avatar-fg);',
'}',
'',
'/* foto por cima das iniciais; se falhar, o onerror remove a <img> */',
'.ch-avatar img {',
'    position: absolute;',
'    inset: 0;',
'    width: 100%;',
'    height: 100%;',
'    object-fit: cover;',
'    border-radius: 50%;',
'}',
'',
'.ch-dot {',
'    position: absolute;',
'    right: -1px;',
'    bottom: -1px;',
'    width: 10px;',
'    height: 10px;',
'    border-radius: 50%;',
'    border: 2px solid #fff;',
'}',
'',
'.ch-dot--online  { background: var(--ch-online); }',
'.ch-dot--ausente { background: var(--ch-ausente); }',
'.ch-dot--offline { background: var(--ch-offline); }',
'',
unistr('/* nome e cargo cortam com retic\00EAncias em vez de quebrar a linha */'),
'.ch-contact-txt {',
'    display: flex;',
'    flex-direction: column;',
'    min-width: 0;',
'}',
'',
'.ch-contact-txt b,',
'.ch-contact-txt small {',
'    white-space: nowrap;',
'    overflow: hidden;',
'    text-overflow: ellipsis;',
'}',
'',
'.ch-contact-txt b {',
'    font-size: 13px;',
'    font-weight: 600;',
'    color: var(--ch-text);',
'}',
'',
'.ch-contact-txt small {',
'    font-size: 11px;',
'    color: var(--ch-text-dim);',
'}',
'',
'/* ============================================',
'   Painel de conversa',
'   ============================================ */',
'',
'.ch-chat {',
'    display: flex;',
'    flex-direction: column;',
'    min-height: 0;',
'    overflow: hidden;',
'    background: #fff;',
'}',
'',
unistr('/* repassa a altura pela cadeia de wrappers at\00E9 .ch-msgs.'),
unistr('   O :not(.ch-composer) impede que o composer vire coluna e cres\00E7a. */'),
'.ch-chat>div,',
'.ch-chat .col,',
'.ch-chat .col>div,',
'.ch-chat .col>div>div:not(.ch-composer) {',
'    display: flex;',
'    flex-direction: column;',
'    flex: 1 1 auto;',
'    min-height: 0;',
'}',
'',
unistr('/* coluna do composer: altura do conte\00FAdo, sempre no rodap\00E9.'),
'   :has() funciona com a classe ch-composer-col na linha ou na coluna. */',
'.ch-chat .col:has(.ch-composer) {',
'    flex: 0 0 auto;',
'    margin-top: auto;',
'}',
'',
'/* ---- estado vazio (nenhum contato selecionado) ---- */',
'.ch-vazio {',
'    flex: 1 1 auto;',
'    display: flex;',
'    flex-direction: column;',
'    align-items: center;',
'    justify-content: center;',
'    gap: 6px;',
'    padding: 24px;',
'    text-align: center;',
'    color: var(--ch-text-dim);',
'}',
'',
'.ch-vazio .fa {',
'    font-size: 40px;',
'    color: var(--ch-text-faint);',
'    margin-bottom: 6px;',
'}',
'',
'.ch-vazio b {',
'    font-size: 14px;',
'    font-weight: 600;',
'    color: var(--ch-text);',
'}',
'',
'.ch-vazio small {',
'    font-size: 12px;',
'}',
'',
unistr('/* ---- cabe\00E7alho da conversa (contato aberto) ---- */'),
'.ch-head {',
'    display: flex;',
'    flex: 0 0 auto;',
'    align-items: center;',
'    gap: 10px;',
'    padding: 10px 24px;',
'    border-bottom: 1px solid var(--ch-border);',
'    background: #fff;',
'}',
'',
unistr('/* sem contato: s\00F3 o estado vazio; com contato: cabe\00E7alho + mensagens + composer */'),
'.ch-chat:not(.is-aberto) .ch-head,',
'.ch-chat:not(.is-aberto) .container {',
'    display: none !important;',
'}',
'',
'.ch-chat.is-aberto .ch-vazio {',
'    display: none;',
'}',
'',
'/* ---- mensagens ---- */',
'.ch-msgs {',
'    flex: 1 1 auto;',
'    min-height: 0;',
'    overflow-y: auto;',
'    display: flex;',
'    flex-direction: column;',
'    gap: 18px;',
'    padding: 24px;',
'    background: #fff;',
'}',
'',
unistr('/* "nenhuma mensagem" do relat\00F3rio */'),
'.ch-chat .nodatafound {',
'    padding: 24px;',
'    text-align: center;',
'    font-size: 13px;',
'    color: var(--ch-text-faint);',
'}',
'',
'.ch-sep {',
'    flex: 0 0 auto;',
'    margin: 6px 0;',
'    text-align: center;',
'}',
'',
'.ch-sep span {',
'    font-size: 11px;',
'    font-weight: 600;',
'    letter-spacing: .04em;',
'    color: var(--ch-text-faint);',
'}',
'',
'.ch-msg {',
'    display: flex;',
'    flex: 0 0 auto;',
'}',
'',
'.ch-msg--out {',
'    justify-content: flex-end;',
'}',
'',
'.ch-bubble {',
'    max-width: 420px;',
'    padding: 10px 13px;',
'    border-radius: var(--ch-radius);',
'    font-size: 13px;',
'    line-height: 1.45;',
'    overflow-wrap: anywhere;',
'}',
