,p_action_sequence=>20
,p_execute_on_page_init=>'N'
,p_name=>'Gravar mensagem'
,p_static_id=>'gravar-mensagem'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'items_to_submit', 'P4_MENSAGEM,P4_CANAL_ID',
  'language', 'PLSQL',
  'plsql_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'declare',
    '  l_eu    colaborador.id_colaborador%type;',
    '  l_texto varchar2(32767) := trim(:P4_MENSAGEM);',
    'begin',
    '  if l_texto is null then',
    '    return;',
    '  end if;',
    '',
    '  begin',
    '    select id_colaborador',
    '    into   l_eu',
    '    from   colaborador',
    '    where  upper(login_apex) = upper(:APP_USER)',
    '    fetch  first 1 row only;',
    '  exception',
    '    when no_data_found then',
    '      raise_application_error(-20001,',
    unistr('        ''Seu usu\00E1rio n\00E3o est\00E1 vinculado a um colaborador.'');'),
    '  end;',
    '',
    unistr('  -- P4_CANAL_ID vem do navegador: s\00F3 grava se eu participo do canal'),
    '  insert into canal_mensagem (id_canal, id_colaborador, corpo)',
    '  select cp.id_canal, l_eu, substrb(l_texto, 1, 4000)',
    '  from   canal_participante cp',
    '  where  cp.id_canal       = to_number(:P4_CANAL_ID)',
    '  and    cp.id_colaborador = l_eu;',
    '',
    '  if sql%rowcount = 0 then',
    '    raise_application_error(-20003,',
    unistr('      ''Voc\00EA n\00E3o participa desta conversa.'');'),
    '  end if;',
    '',
    '  :P4_MENSAGEM := null;',
    'end;')),
  'show_processing', 'N')).to_clob
,p_wait_for_result=>'Y'
);
