    'const campo = document.getElementById("ch-texto");',
    'const texto = campo.value.trim();',
    '',
    unistr('// nada para enviar ou nenhuma conversa aberta: interrompe as pr\00F3ximas a\00E7\00F5es'),
    'if (!texto || !apex.item("P4_CANAL_ID").getValue()) {',
    '    campo.focus();',
    '    apex.da.cancelEvent.call(this);',
    '    return;',
    '}',
    '',
    'apex.item("P4_MENSAGEM").setValue(texto);',
    'chChat.irParaFim();',
    unistr('// limpa j\00E1, para um segundo clique n\00E3o reenviar a mesma mensagem'),
    'campo.value = "";',
    'campo.focus();')))).to_clob
);
