,p_execute_on_page_init=>'N'
,p_name=>'Marcar contato selecionado'
,p_static_id=>'marcar-contato-selecionado'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'js_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'const contato = this.triggeringElement;',
    'apex.item("P4_CONTATO_ID").setValue(contato.dataset.id);',
    '',
    'document.querySelectorAll(".ch-contact.is-active")',
