wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(9290214556503210)
,p_event_id=>wwv_flow_imp.id(9289913220503207)
,p_event_result=>'TRUE'
,p_action_sequence=>30
,p_execute_on_page_init=>'N'
,p_name=>'Obter canal direto'
,p_static_id=>'obter-canal-direto'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'items_to_return', 'P4_CANAL_ID',
  'items_to_submit', 'P4_CONTATO_ID',
  'language', 'PLSQL',
  'plsql_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'declare',
    '  l_eu      colaborador.id_colaborador%type;',
    '  l_empresa colaborador.id_empresa%type;',
    '  l_valido  number;',
    'begin',
    '  begin',
    '    select id_colaborador, id_empresa',
    '    into   l_eu, l_empresa',
    '    from   colaborador',
    '    where  upper(login_apex) = upper(:APP_USER)',
    '    fetch  first 1 row only;',
    '  exception',
    '    when no_data_found then',
    '      raise_application_error(-20001,',
    unistr('        ''Seu usu\00E1rio n\00E3o est\00E1 vinculado a um colaborador.'');'),
    '  end;',
    '',
    unistr('  -- P4_CONTATO_ID vem do navegador: s\00F3 abre conversa com'),
    '  -- colaborador ativo, da mesma empresa e diferente de mim',
    '  select count(*)',
    '  into   l_valido',
    '  from   colaborador',
    '  where  id_colaborador = to_number(:P4_CONTATO_ID)',
    '  and    id_empresa     = l_empresa',
    '  and    status         = true',
    '  and    id_colaborador != l_eu;',
    '',
    '  if l_valido = 0 then',
    '    raise_application_error(-20002,',
    unistr('      ''N\00E3o \00E9 poss\00EDvel abrir conversa com este colaborador.'');'),
    '  end if;',
    '',
    '  :P4_CANAL_ID := ch_get_canal_direto(l_eu, to_number(:P4_CONTATO_ID));',
    'end;')),
  'show_processing', 'N',
  'suppress_change_event', 'N')).to_clob
,p_wait_for_result=>'Y'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(9292820097503236)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'CH_VERIFICAR_MSGS'
,p_static_id=>'ch-verificar-msgs'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  l_canal  number := to_number(apex_application.g_x01 default null on conversion error);',
'  l_ultima canal_mensagem.id_canal_mensagem%type;',
'  l_qtd    number;',
'begin',
unistr('  -- mesma regra da regi\00E3o Mensagens: s\00F3 canais de que o usu\00E1rio logado participa.'),
unistr('  -- "\00FAltima" = a mais recente pela mesma ordem da regi\00E3o (data_envio, id).'),
'  select max(m.id_canal_mensagem) keep (dense_rank last order by m.data_envio, m.id_canal_mensagem),',
'         count(*)',
'  into   l_ultima, l_qtd',
'  from   canal_mensagem m',
'  where  m.id_canal = l_canal',
'  and    nvl(m.excluida, false) = false',
'  and    exists (',
'           select 1',
'           from   canal_participante cp',
'           join   colaborador eu on eu.id_colaborador = cp.id_colaborador',
'           where  cp.id_canal = m.id_canal',
'           and    upper(eu.login_apex) = upper(:APP_USER)',
'         );',
'',
unistr('  -- mesmo formato que o JS monta a partir da tela: "<\00FAltima>:<quantidade>".'),
unistr('  -- A quantidade \00E9 limitada a 200, o Number of Rows da regi\00E3o.'),
'  apex_json.open_object;',
'  apex_json.write(''assinatura'', nvl(l_ultima, 0) || '':'' || least(l_qtd, 200));',
'  apex_json.close_object;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>9292820097503236
);
end;
