,p_validation_name=>unistr('Forma\00E7\00E3o da empresa')
,p_static_id=>unistr('forma\00E7\00E3o-da-empresa')
,p_validation_sequence=>10
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  l_qt pls_integer;',
'begin',
'  if :P21_ID_FORMACAO is not null then',
'    select count(*) into l_qt',
'      from formacao_colaborador',
'     where id_formacao = :P21_ID_FORMACAO',
'       and id_empresa  = :G_ID_EMPRESA;',
'  else',
'    select count(*) into l_qt',
'      from colaborador',
'     where id_colaborador = :P21_ID_COLABORADOR',
'       and id_empresa     = :G_ID_EMPRESA;',
'  end if;',
'  return l_qt = 1;',
'end;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>unistr('Forma\00E7\00E3o n\00E3o encontrada.')
