'begin',
'  if pkg_ponto.fn_pode_aprovar(:P33_ID_AJUSTE) <> ''S'' then',
unistr('    raise_application_error(-20067, ''Voc\00EA n\00E3o pode responder a este pedido: ele cabe ao gestor direto ou ao RH.'');'),
'  end if;',
'',
'  select c.nome_completo,',
unistr('         to_char(a.dt_referencia, ''DD/MM/YYYY'') || '' \00B7 '''),
'         || case a.tp_ajuste',
'              when ''ABONO'' then ''Abonar o dia''',
'              else case a.tp_marcacao',
'                     when ''ENTRADA''   then ''Entrada''',
unistr('                     when ''INTERVALO'' then ''Sa\00EDda para intervalo'''),
'                     when ''RETORNO''   then ''Retorno do intervalo''',
unistr('                     else ''Sa\00EDda'''),
unistr('                   end || '' \00E0s '' || to_char(a.dh_solicitada, ''HH24:MI'')'),
'            end,',
'         a.ds_motivo',
'    into :P33_NM_COLABORADOR, :P33_DS_PEDIDO, :P33_DS_MOTIVO',
'    from ponto_ajuste a',
'    join colaborador c on c.id_colaborador = a.id_colaborador',
'   where a.id_ajuste  = :P33_ID_AJUSTE',
'     and a.id_empresa = :G_ID_EMPRESA',
'     and a.st_ajuste  = ''PENDENTE'';',
'exception',
'  when no_data_found then',
unistr('    raise_application_error(-20066, ''Pedido n\00E3o encontrado ou j\00E1 respondido.'');'),
'end;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>44207442385570304
);
